      <div className="card">
        <h3 style={{fontWeight:700,fontSize:14,color:'#2B3BB5',marginBottom:14}}>Recent Payments</h3>
        {completed.length===0
          ?<p style={{color:'#94a3b8',fontSize:13}}>No completed jobs yet</p>
